from pathlib import Path
import json,hashlib,shutil,copy
R=Path(__file__).resolve().parent;V=R.parents[2];S=V/'support/p5-next-family-briefs';B=V/'actors/b/banner'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
assert not (R/'generation.json').exists(),'Non-destructive preparation only; never recreate existing call records'
plan=json.loads((S/'chariot/plan.json').read_text(encoding='utf-8'));records=[]
for directory in ['prompts','inputs/core','sources','tool','review']: (R/directory).mkdir(parents=True,exist_ok=True)
for item in plan['jobs']:
 if item['identityId']!='b':continue
 oldid=item['id'];sid=oldid.replace('-planned','-r1');text=(S/item['prompt']).read_text(encoding='utf-8');assert sha(S/item['prompt'])==item['promptSha256']
 if item['group']=='core':
  text+='\nImage4 is own Tịch Bạch Banner SAME-DIRECTION native nearest8x CAMERA/HAIR/FACE support only. Its body poses, ivory ritual robe and seal panels MUST NOT transfer to the Cart outfit. Image1 own Cart P1 remains PRIMARY for identity/body proportions/BLUE-CHARCOAL STEEL armor and costume; Image3 ownCart source reinforces that outfit. Image4 helps exact requested camera and same silver hair/head identity only, never replaces the PRIMARY. Requested facing is higher priority than the southeast angle of Image1/3. All30 sprites including every ready, release and recovery keep exact camera from Image2/4. Redraw each view; no mirror. Keep at least48px empty outer margin and24px gaps around full crown, wide gauntlets and dark boots.\n'
 prompt=R/'prompts'/f'{sid}.txt';prompt.write_text(text.rstrip()+'\n',encoding='utf-8')
 r={'id':sid,'identityId':'b','familyId':'chariot','direction':item['direction'],'group':item['group'],'actions':item['actions'],'calibrationCells':6,'prompt':str(prompt.relative_to(V)).replace('\\','/'),'promptSha256':sha(prompt),'raw':f'actors/b/chariot/sources/{sid}.png','inputs':[],'inputSnapshotsReady':False,'dependency':None if item['group']=='core' else f'chariot-b-{item["direction"]}-core-r1 actual reviewed own Cart neutral','tool':'built-in-imagegen','transparentRequested':True,'requestedGrid':item['requestedGrid'],'requestedSourcePoses':item['requestedSourcePoses'],'status':'prepared-awaiting-Banner128-technical-gate' if item['group']=='core' else 'prepared-awaiting-own-reviewed-same-view-Cart-neutral','selected':False,'ownerApproved':False,'runtimeIntegrated':False,'preparedPromptBasis':str((S/item['prompt']).relative_to(V)).replace('\\','/'),'preparedPromptBasisSha256':item['promptSha256']}
 if item['group']=='core':
  for i,old in enumerate(item['inputs'],1):
   source=S/old['file'];assert sha(source)==old['sha256'];dst=R/'inputs/core'/sid/f'{i}.png';dst.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(source,dst)
   r['inputs'].append({**old,'file':str(dst.relative_to(V)).replace('\\','/'),'original':str(source),'role':['own-approved-B-chariot-P1-PRIMARY','Wang-same-view-camera-anatomy-pixel-support-only','own-approved-B-chariot-P1-full-source-costume-support'][i-1]})
  source=B/'inputs/neutral'/f'banner-b-{item["direction"]}-nearest8x.png';assert source.exists();dst=R/'inputs/core'/sid/'4.png';shutil.copy2(source,dst);r['inputs'].append({'file':str(dst.relative_to(V)).replace('\\','/'),'sha256':sha(dst),'original':str(source),'role':'own-same-identity-B-same-view-hair-face-camera-support-only-NOT-Banner-outfit','index':4});r['inputSnapshotsReady']=True
 records.append(r)
data={'schema':'equipment-body-generation-v2','identityId':'b','familyId':'chariot','date':'2026-10-14','generationAllowed':False,'requiredGate':'Explicit root release after Banner128 scoped CPU/lineage/browser/Three and checkpoint; preparation is not generation dispatch.','records':records,'forecast':{'sources':24,'clips':64,'motionKeysAtSix':384,'neutralCalibrationsAtSix':144},'actualCoverage':{'generatedSources':0,'clips':0,'motionKeys':0},'ownerApproved':False,'runtimeIntegrated':False,'choreographyPolicy':'Body commands separate world-ground Cart at caster+[55,0] through empty open/seal palms. No physical hand grip, no baked device/chain/beast/FX. Every source actual hands/cuffs/support roots reviewed; one source factor.'}
(R/'generation.json').write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
timing={'idle':[150]*6,'run':[100]*6,'hit':[60,60,80,100,100,160],'death':[140,140,180,180,200,500],'meditate':[260]*6,'gather':[180,200,200,260,200,260],'cast-single-target':[220,240,240,260,220,300],'cast-aoe':[300,270,280,420,400,590]}
recipe={'schema':'equipment-B-chariot-pack-recipe-v1','status':'prepared-no-generated-body','bodyNominalPx':80,'normalCanvas':[112,112],'normalPivot':[56,104],'deathCanvas':[192,128],'deathPivot':[96,112],'scalePolicy':'One isotropic factor/source from real ownCart neutral crown to actual dark boot soles; no per-pose fit, face transplant or mirror.','sourceMaskPolicy':'Measured actual full-source bodies/fragments, alpha128 body only; raw RGBA unchanged.','socketPolicy':'Actual empty command palm/cuff, open/seal/occluded honestly. gripHeld false; world-ground device never attached to wrist; occluded estimates retain uncertainty.','rootPolicy':'Actual supported boots, semantic run/body support projection; seated/prone anatomical support with uncertainty, lift baked once.','timingMs':timing,'releaseMs':{'cast-single-target':700,'cast-aoe':850},'phaseMapping':'Fourth key starts fixture release700/850; Core facts alone create rails/nodes/contact, source pose never grants hit.','pathsRelativeTo':'wang-lin-equipment-production-v2','clipIdTemplate':'chariot-b-{direction}-{action}','ownerApproved':False,'runtimeIntegrated':False}
(R/'pack-recipe.json').write_text(json.dumps(recipe,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
checks=[]
for r in records:
 assert sha(V/r['prompt'])==r['promptSha256'];checks.append('prompt:'+r['id'])
 for p in r['inputs']:assert sha(V/p['file'])==p['sha256'];checks.append('input:'+r['id']+p['file'])
(R/'review/preparation-verification.json').write_text(json.dumps({'status':'passed','checkCount':len(checks),'jobs':24,'coreReadyTripletsPlusOwnViewSupport':8,'actualGeneration':0,'generationAllowed':False,'generationSha256':sha(R/'generation.json'),'checks':checks,'ownerApproved':False},indent=2)+'\n',encoding='utf-8')
print(json.dumps({'jobs':24,'readyCoreInputs':8,'checks':len(checks),'generationAllowed':False,'generationSha256':sha(R/'generation.json')}))
